describe('Animated transitions between async page loads', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.viewport(1280, 720);
  });

  it('should display fade-in animation when loading async content', () => {
    cy.get('[data-testid="load-async-content"]').click();

    cy.get('[data-testid="loading-spinner"]').should('be.visible');

    cy.get('[data-testid="async-content"]', { timeout: 10000 })
      .should('exist')
      .and('have.css', 'opacity', '1');

    cy.get('[data-testid="async-content"]')
      .should('have.class', 'fade-in-animation');

    cy.get('[data-testid="loading-spinner"]').should('not.exist');
  });

  it('should handle rapid consecutive page transitions with animation queuing', () => {
    cy.get('[data-testid="load-async-content"]').click();
    cy.get('[data-testid="async-content"]', { timeout: 10000 }).should('exist');

    cy.get('[data-testid="transition-button-1"]').click();
    cy.get('[data-testid="page-1-content"]', { timeout: 10000 })
      .should('be.visible')
      .and('have.css', 'opacity', '1');

    cy.get('[data-testid="transition-button-2"]').click();
    cy.get('[data-testid="page-2-content"]', { timeout: 10000 })
      .should('be.visible')
      .and('have.css', 'opacity', '1');

    cy.get('[data-testid="page-1-content"]').should('not.be.visible');
  });

  it('should maintain animation state during network delay', () => {
    cy.intercept('GET', '/api/async-data', (req) => {
      req.reply((res) => {
        res.delay(2000);
        res.send({
          statusCode: 200,
          body: { data: 'test content' }
        });
      });
    }).as('slowLoad');

    cy.get('[data-testid="load-async-content"]').click();
    cy.get('[data-testid="loading-spinner"]').should('be.visible');

    cy.wait('@slowLoad');
    cy.get('[data-testid="async-content"]')
      .should('exist')
      .and('have.class', 'fade-in-animation');
  });

  it('should handle animation completion before next transition', () => {
    cy.get('[data-testid="load-async-content"]').click();
    cy.get('[data-testid="async-content"]', { timeout: 10000 }).should('exist');

    cy.get('[data-testid="async-content"]')
      .should('have.css', 'animation-play-state', 'running')
      .or('have.css', 'animation-play-state', 'paused');

    cy.wait(1000);

    cy.get('[data-testid="transition-button"]').click();
    cy.get('[data-testid="new-page-content"]', { timeout: 10000 })
      .should('be.visible')
      .and('have.class', 'fade-in-animation');
  });

  it('should handle failed async load with error animation', () => {
    cy.intercept('GET', '/api/async-data', {
      statusCode: 500,
      body: { error: 'Server error' }
    }).as('failedLoad');

    cy.get('[data-testid="load-async-content"]').click();
    cy.get('[data-testid="loading-spinner"]').should('be.visible');

    cy.wait('@failedLoad');
    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .and('have.class', 'error-animation');
  });

  it('should preserve animation timing across multiple transitions', () => {
    const transitionDuration = 300;

    cy.get('[data-testid="load-async-content"]').click();
    cy.get('[data-testid="async-content"]', { timeout: 10000 })
      .should('have.css', 'animation-duration')
      .and('include', 'ms');

    cy.get('[data-testid="transition-button-1"]').click();
    cy.get('[data-testid="page-1-content"]', { timeout: 10000 }).should('exist');

    cy.get('[data-testid="transition-button-2"]').click();
    cy.get('[data-testid="page-2-content"]', { timeout: 10000 }).should('exist');

    cy.get('[data-testid="page-2-content"]')
      .should('have.css', 'animation-duration')
      .and('include', 'ms');
  });
});
